def market_burst_bandwidth_gbps(msgs_per_sec=10_000_000, bytes_per_msg=64):
    bytes_sec = msgs_per_sec * bytes_per_msg
    return round((bytes_sec * 8) / 1e9, 2)  # 5.12 Gbps

def verify_numa_pinning(nic_numa_node, thread_numa_node):
    if nic_numa_node != thread_numa_node:
        raise RuntimeError(f'NUMA mismatch: NIC={nic_numa_node}, Thread={thread_numa_node}')

def deterministic_replay(wire_log_path, strategy_engine):
    for tick in chronicle_reader(wire_log_path):
        strategy_engine.set_virtual_clock(tick.ptp_ns)
        strategy_engine.on_tick(tick)

def monitor_nic_health(prev_drops, curr_drops, gap_age_ms):
    if curr_drops > prev_drops or gap_age_ms > 5.0:
        strategy_kill_switch.halt_quoting('STALE_MARKET_DATA')
        return 'HALTED'
    return 'ACTIVE'
